#include <bits/stdc++.h>
using namespace std;

const int L = 18;        // 2^17 = 131072 > 1e5
const int MAXN = 200005;

int n, m;
int t[MAXN];             // 1..2n 的倍长数组
int nxt[MAXN];           // nxt[i]: 从 i 开始包含全部 m 种宝石的最短长度
int jump_[19][MAXN];     // jump_[k][i]: 从 i 起连续走 2^k 个 greedy 窗口的总长度

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    for (int i = 1; i <= n; ++i) {
        cin >> t[i];
        t[i + n] = t[i];
    }

    // 双指针求 nxt[i]
    vector<int> cnt(m + 1, 0);
    int kinds = 0, r = 1;
    for (int i = 1; i <= n; ++i) {
        while (r <= i + n - 1 && kinds < m) {
            if (++cnt[t[r]] == 1) ++kinds;
            ++r;
        }
        nxt[i] = r - i;              // 窗口为 [i, r-1]
        if (--cnt[t[i]] == 0) --kinds;
    }

    for (int i = 1; i <= n; ++i) jump_[0][i] = nxt[i];
    for (int k = 1; k <= L; ++k)
        for (int i = 1; i <= n; ++i) {
            int tar = (i - 1 + jump_[k - 1][i]) % n + 1;
            long long v = (long long)jump_[k - 1][i] + jump_[k - 1][tar];
            jump_[k][i] = (int)min(v, (long long)1e9);
        }

    int ans = 0;
    for (int s = 1; s <= n; ++s) {
        int cur = s, used = 0, got = 0;
        for (int k = L; k >= 0; --k) {
            if (used + jump_[k][cur] <= n) {
                used += jump_[k][cur];
                got += 1 << k;
                cur = (cur - 1 + jump_[k][cur]) % n + 1;
            }
        }
        ans = max(ans, got);
    }
    cout << ans << '\n';
    return 0;
}
